-- ============================================================
-- Badge catalog seed — 100 badges from docs/badge-manifest.csv.
-- rarity normalized to the table's lowercase enum; tiered/flagship→rep value,
-- the tiered flag captures range badges. Idempotent (on conflict do update).
-- earn_rule jsonb = {trigger, rule} — seed for the award engine.
-- ============================================================

on conflict (code) do update set name=excluded.name, description=excluded.description, category=excluded.category, rarity=excluded.rarity, tiered=excluded.tiered, hidden=excluded.hidden, emblem_key=excluded.emblem_key, earn_rule=excluded.earn_rule, sort_order=excluded.sort_order, active=true;
